metastore.ejemplo:
-- adentro de beeline
DESCRIBE FORMATTED ventas;
-- buscá la línea Location: hdfs://.../user/root/ventas

tez.ejemplo:
-- adentro de beeline
SET hive.execution.engine;
-- responde: hive.execution.engine=tez

pig.ejemplo:
ventas = LOAD '/user/root/ventas' USING PigStorage(',')
  AS (fecha:chararray, sucursal:chararray, producto:chararray,
      cantidad:int, precio:int);
por_prod = GROUP ventas BY producto;
DUMP por_prod;

